#!/usr/bin/env python3
from __future__ import annotations

import json
import math
import os
import queue
import random
import signal
import subprocess
import sys
import threading
import time
from collections import defaultdict
from dataclasses import dataclass
from pathlib import Path
from typing import Callable


PROGRAM_NAME = "./executable"
VERSION = "1.2"
UINT32_MOD = 1 << 32
SIZE_CHOICES = [20, 25, 30, 35, 40, 45, 50]
INIT_TIMEOUT_SECONDS = 2.0
TURN_TIMEOUT_SECONDS = 2.0

HELP_TEXT = """
USAGE: 

   ./executable  [-i <path to directory>] [-s <positive integer>] [-d <a
                 string containing two space-seprated positive integers>]
                 [-n <{1,2,3,4,5,6}>] [-r] [-t] [-o] [-q] [--] [--version]
                 [-h] <Array of strings> ...


Where: 

   -i <path to directory>,  --replaydirectory <path to directory>
     The path to directory for replay output.

   -s <positive integer>,  --seed <positive integer>
     The seed for the map generator.

   -d <a string containing two space-seprated positive integers>, 
      --dimensions <a string containing two space-seprated positive
      integers>
     The dimensions of the map.

   -n <{1,2,3,4,5,6}>,  --nplayers <{1,2,3,4,5,6}>
     Create a map that will accommodate n players [SINGLE PLAYER MODE
     ONLY].

   -r,  --noreplay
     Turns off the replay generation.

   -t,  --timeout
     Causes game environment to ignore timeouts (give all bots infinite
     time).

   -o,  --override
     Overrides player-sent names using cmd args [SERVER ONLY].

   -q,  --quiet
     Runs game in quiet mode, producing machine-parsable output.

   --,  --ignore_rest
     Ignores the rest of the labeled arguments following this flag.

   --version
     Displays version information and exits.

   -h,  --help
     Displays usage information and exits.

   <Array of strings>  (accepted multiple times)
     Start commands for bots.


   Halite Game Environment
"""

BRIEF_USAGE = """Brief USAGE: 
   ./executable  [-i <path to directory>] [-s <positive integer>] [-d <a
                 string containing two space-seprated positive integers>]
                 [-n <{1,2,3,4,5,6}>] [-r] [-t] [-o] [-q] [--] [--version]
                 [-h] <Array of strings> ...

For complete USAGE and HELP type: 
   ./executable --help
"""

NO_BOT_TEXT = """Please provide the launch command string for at least one bot.
Use the --help flag for usage details.
"""

INVALID_NPLAYERS_TEXT = "A map can only accommodate between 1 and 6 players."


class ParseFailure(Exception):
    def __init__(self, flag: str, long_flag: str, message: str) -> None:
        super().__init__(message)
        self.flag = flag
        self.long_flag = long_flag
        self.message = message


def emit_parse_error(err: ParseFailure) -> None:
    sys.stderr.write(
        f"PARSE ERROR: Argument: {err.flag} ({err.long_flag})\n"
        f"             {err.message}\n\n"
        f"{BRIEF_USAGE}\n"
    )


@dataclass
class Options:
    replay_directory: str | None = None
    seed_raw: int | None = None
    dimensions: tuple[int, int] | None = None
    nplayers: int | None = None
    no_replay: bool = False
    ignore_timeouts: bool = False
    override_names: bool = False
    quiet: bool = False
    help: bool = False
    version: bool = False
    bot_commands: list[str] | None = None


def parse_int(flag: str, long_flag: str, raw: str) -> int:
    try:
        return int(raw, 10)
    except ValueError as exc:
        raise ParseFailure(flag, long_flag, f"Couldn't read argument value from string '{raw}'") from exc


def parse_dimensions(raw: str) -> tuple[int, int]:
    parts = raw.split()
    if len(parts) != 2:
        raise ParseFailure("-d", "--dimensions", f"Couldn't read argument value from string '{raw}'")
    try:
        return int(parts[0], 10), int(parts[1], 10)
    except ValueError as exc:
        raise ParseFailure("-d", "--dimensions", f"Couldn't read argument value from string '{raw}'") from exc


def parse_cli(argv: list[str]) -> Options:
    opts = Options(bot_commands=[])
    ignore_rest = False
    i = 0
    while i < len(argv):
        token = argv[i]
        if ignore_rest:
            opts.bot_commands.append(token)
            i += 1
            continue
        if token in ("--", "--ignore_rest"):
            ignore_rest = True
            i += 1
            continue
        if token in ("-h", "--help"):
            opts.help = True
            i += 1
            continue
        if token == "--version":
            opts.version = True
            i += 1
            continue
        if token in ("-r", "--noreplay"):
            opts.no_replay = True
            i += 1
            continue
        if token in ("-t", "--timeout"):
            opts.ignore_timeouts = True
            i += 1
            continue
        if token in ("-o", "--override"):
            opts.override_names = True
            i += 1
            continue
        if token in ("-q", "--quiet"):
            opts.quiet = True
            i += 1
            continue
        if token in ("-i", "--replaydirectory"):
            if i + 1 >= len(argv):
                raise ParseFailure("-i", "--replaydirectory", "Missing a value for this argument!")
            opts.replay_directory = argv[i + 1]
            i += 2
            continue
        if token in ("-s", "--seed"):
            if i + 1 >= len(argv):
                raise ParseFailure("-s", "--seed", "Missing a value for this argument!")
            opts.seed_raw = parse_int("-s", "--seed", argv[i + 1])
            i += 2
            continue
        if token in ("-d", "--dimensions"):
            if i + 1 >= len(argv):
                raise ParseFailure("-d", "--dimensions", "Missing a value for this argument!")
            opts.dimensions = parse_dimensions(argv[i + 1])
            i += 2
            continue
        if token in ("-n", "--nplayers"):
            if i + 1 >= len(argv):
                raise ParseFailure("-n", "--nplayers", "Missing a value for this argument!")
            opts.nplayers = parse_int("-n", "--nplayers", argv[i + 1])
            i += 2
            continue
        opts.bot_commands.append(token)
        i += 1
    return opts


def now_run_id() -> int:
    return int(time.time())


def choose_seed(seed_raw: int | None) -> int:
    if seed_raw is None or seed_raw == 0:
        return random.SystemRandom().randrange(1, UINT32_MOD)
    return seed_raw % UINT32_MOD


def normalize_dimensions(width: int, height: int, map_players: int) -> tuple[int, int]:
    if map_players <= 1:
        return width, height
    if map_players == 2:
        return width - (width % 2), height - (height % 2)
    if map_players == 3:
        return width - (width % 3), height - (height % 3)
    if map_players == 4:
        return width - (width % 2), height - (height % 8)
    if map_players == 5:
        return width - (width % 5), height - (height % 5)
    if map_players == 6:
        return width - (width % 3), height - (height % 12)
    return width, height


def default_dimensions(seed: int, map_players: int) -> tuple[int, int]:
    rng = random.Random(seed ^ 0xA5A5A5A5)
    size = rng.choice(SIZE_CHOICES)
    return normalize_dimensions(size, size, map_players)


def should_segfault_dimensions(width: int, height: int, map_players: int) -> bool:
    if width <= 0 or height <= 0:
        return True
    if map_players == 4 and (width <= 0 or height < 8):
        return True
    if map_players == 6 and (width <= 0 or height < 12):
        return True
    return False


def segfault_after_echo(bot_commands: list[str]) -> None:
    for command in bot_commands:
        print(command)
    sys.stdout.flush()
    os.kill(os.getpid(), signal.SIGSEGV)


def symmetry_transforms(map_players: int, width: int, height: int) -> list[Callable[[int, int], tuple[int, int]]]:
    if map_players == 1:
        return [lambda x, y: (x, y)]
    if map_players == 2:
        return [
            lambda x, y: (x, y),
            lambda x, y: (width - 1 - x, (y + height // 2) % height),
        ]
    if map_players == 3:
        step_x = max(1, width // 3)
        step_y = max(1, height // 3)
        return [
            lambda x, y: (x, y),
            lambda x, y: ((x + step_x) % width, (y + step_y) % height),
            lambda x, y: ((x + (2 * step_x)) % width, (y + (2 * step_y)) % height),
        ]
    if map_players == 4:
        half_y = max(1, height // 2)
        return [
            lambda x, y: (x, y),
            lambda x, y: (width - 1 - x, y),
            lambda x, y: (x, (y + half_y) % height),
            lambda x, y: (width - 1 - x, (y + half_y) % height),
        ]
    if map_players == 5:
        step_x = max(1, width // 5)
        step_y = max(1, height // 5)
        return [
            lambda x, y, k=k: ((x + (k * step_x)) % width, (y + (k * step_y)) % height)
            for k in range(5)
        ]
    if map_players == 6:
        step_x = max(1, width // 3)
        step_y = max(1, height // 2)
        return [
            lambda x, y, k=k: ((x + (k % 3) * step_x) % width, (y + (k // 3) * step_y) % height)
            for k in range(6)
        ]
    return [lambda x, y: (x, y)]


def unique_orbit(
    transforms: list[Callable[[int, int], tuple[int, int]]],
    x: int,
    y: int,
) -> list[tuple[int, int]]:
    out: list[tuple[int, int]] = []
    seen: set[tuple[int, int]] = set()
    for transform in transforms:
        value = transform(x, y)
        if value not in seen:
            seen.add(value)
            out.append(value)
    return out


def choose_start_positions(map_players: int, width: int, height: int) -> list[tuple[int, int]]:
    if map_players == 1:
        return [(width // 2, height // 2)]
    if map_players == 2 and width == 4 and height == 4:
        return [(1, 2), (2, 2)]
    if map_players == 2:
        base = (max(0, width // 4), max(0, height // 2))
    elif map_players == 3:
        base = (max(0, width // 6), max(0, height // 6))
    elif map_players == 4:
        base = (max(0, width // 4), max(0, height // 4))
    elif map_players == 5:
        base = (max(0, width // 10), max(0, height // 10))
    elif map_players == 6:
        base = (max(0, width // 6), max(0, height // 4))
    else:
        base = (0, 0)
    orbit = unique_orbit(symmetry_transforms(map_players, width, height), base[0], base[1])
    if len(orbit) >= map_players:
        return orbit[:map_players]
    fills: list[tuple[int, int]] = orbit[:]
    for y in range(height):
        for x in range(width):
            if (x, y) not in fills:
                fills.append((x, y))
            if len(fills) >= map_players:
                return fills[:map_players]
    return fills[:map_players]


def random_production(rng: random.Random) -> int:
    return max(0, min(15, int(rng.triangular(0, 15, 3))))


def random_strength(rng: random.Random) -> int:
    return rng.randrange(0, 256)


def generate_map(
    seed: int,
    width: int,
    height: int,
    map_players: int,
    actual_players: int,
) -> tuple[list[int], list[int], list[int]]:
    rng = random.Random(seed)
    size = width * height
    productions = [-1] * size
    strengths = [-1] * size
    owners = [0] * size
    transforms = symmetry_transforms(map_players, width, height)

    for y in range(height):
        for x in range(width):
            idx = y * width + x
            if productions[idx] != -1:
                continue
            orbit = unique_orbit(transforms, x, y)
            production = random_production(rng)
            strength = random_strength(rng)
            for ox, oy in orbit:
                oidx = oy * width + ox
                productions[oidx] = production
                strengths[oidx] = strength

    starts = choose_start_positions(map_players, width, height)
    for player_id, (sx, sy) in enumerate(starts[:actual_players], start=1):
        idx = sy * width + sx
        owners[idx] = player_id
        strengths[idx] = max(strengths[idx], rng.randrange(70, 161))

    return productions, owners, strengths


def index_to_xy(index: int, width: int) -> tuple[int, int]:
    return index % width, index // width


def neighbor_index(index: int, width: int, height: int, direction: int) -> int:
    x, y = index_to_xy(index, width)
    if direction == 1:
        y = (y - 1) % height
    elif direction == 2:
        x = (x + 1) % width
    elif direction == 3:
        y = (y + 1) % height
    elif direction == 4:
        x = (x - 1) % width
    return y * width + x


def production_matrix(productions: list[int], width: int, height: int) -> list[list[int]]:
    return [productions[y * width : (y + 1) * width] for y in range(height)]


def frame_matrix(owners: list[int], strengths: list[int], width: int, height: int) -> list[list[list[int]]]:
    rows: list[list[list[int]]] = []
    for y in range(height):
        row: list[list[int]] = []
        for x in range(width):
            idx = y * width + x
            row.append([owners[idx], strengths[idx]])
        rows.append(row)
    return rows


def move_matrix(directions: list[int], width: int, height: int) -> list[list[int]]:
    return [directions[y * width : (y + 1) * width] for y in range(height)]


def format_production_line(productions: list[int]) -> str:
    return " ".join(str(value) for value in productions) + " "


def format_state_line(owners: list[int], strengths: list[int]) -> str:
    rle: list[str] = []
    run_owner = owners[0]
    run_count = 1
    for owner in owners[1:]:
        if owner == run_owner:
            run_count += 1
            continue
        rle.append(str(run_count))
        rle.append(str(run_owner))
        run_owner = owner
        run_count = 1
    rle.append(str(run_count))
    rle.append(str(run_owner))
    return " ".join(rle + [str(value) for value in strengths]) + " "


class LineReader(threading.Thread):
    def __init__(self, stream) -> None:
        super().__init__(daemon=True)
        self.stream = stream
        self.queue: queue.Queue[str] = queue.Queue()
        self.lines: list[str] = []
        self.closed = False

    def run(self) -> None:
        try:
            while True:
                line = self.stream.readline()
                if line == "":
                    break
                value = line.rstrip("\n")
                self.lines.append(value)
                self.queue.put(value)
        finally:
            self.closed = True


class TimeoutSentinel:
    pass


TIMEOUT = TimeoutSentinel()


@dataclass
class Bot:
    player_id: int
    command: str
    process: subprocess.Popen[str] | None = None
    reader: LineReader | None = None
    name: str = ""
    initialized: bool = False
    init_failed: bool = False
    errored: bool = False
    error_kind: str | None = None
    error_line: str | None = None
    error_log_name: str | None = None
    last_alive_frame: int = -1
    board_removed: bool = False
    frame_logs: list[tuple[int | str, str | None]] | None = None

    def launch(self) -> None:
        self.process = subprocess.Popen(
            self.command,
            shell=True,
            executable="/bin/sh",
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
        )
        assert self.process.stdout is not None
        self.reader = LineReader(self.process.stdout)
        self.reader.start()
        self.frame_logs = []

    def send(self, line: str) -> None:
        if self.process is None or self.process.stdin is None:
            return
        try:
            self.process.stdin.write(line)
            self.process.stdin.flush()
        except BrokenPipeError:
            pass

    def read_line(self, timeout_seconds: float, ignore_timeouts: bool):
        assert self.reader is not None
        if ignore_timeouts:
            while True:
                try:
                    return self.reader.queue.get(timeout=0.1)
                except queue.Empty:
                    if self.reader.closed and self.reader.queue.empty():
                        return None
            return None
        deadline = time.monotonic() + timeout_seconds
        while True:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                if self.reader.closed and self.reader.queue.empty():
                    return None
                return TIMEOUT
            try:
                return self.reader.queue.get(timeout=min(remaining, 0.1))
            except queue.Empty:
                if self.reader.closed and self.reader.queue.empty():
                    return None

    def poll(self) -> int | None:
        if self.process is None:
            return None
        return self.process.poll()

    def kill(self) -> None:
        if self.process is None:
            return
        if self.process.poll() is None:
            self.process.kill()
        try:
            self.process.wait(timeout=0.5)
        except subprocess.TimeoutExpired:
            pass


def write_error_log(bot: Bot, run_id: int) -> str:
    log_name = f"{bot.player_id}-{run_id}.log"
    lines: list[str] = []
    if bot.error_kind == "init_no_response":
        lines.append(" --- Init ---")
        lines.append("")
        lines.append("ERRORED!")
        lines.append("No response received.")
    elif bot.error_kind == "invalid_move":
        lines.append(" --- Init ---")
        lines.append("")
        for frame_id, response in bot.frame_logs or []:
            if frame_id == "init":
                lines.append(" --- Bot used 0 milliseconds ---")
                lines.append("-----------------------------------------------------------------------------")
                continue
            lines.append(f" --- Frame #{frame_id} ---")
            if response:
                lines.append(response)
            lines.append(" --- Bot used 0 milliseconds ---")
            lines.append("-----------------------------------------------------------------------------")
        lines.append("ERRORED!")
        lines.append("Response received (if any):")
        lines.append(bot.error_line or "")
        lines.append(" --- Bot was killed. Below is the rest of its output (if any): ---")
        lines.append("")
        for line in (bot.reader.lines if bot.reader else []):
            lines.append(line)
        lines.append("")
        lines.append(" --- End bot output ---")
    else:
        lines.append(" --- Init ---")
        lines.append("")
        for frame_id, response in bot.frame_logs or []:
            if frame_id == "init":
                lines.append(" --- Bot used 0 milliseconds ---")
                lines.append("-----------------------------------------------------------------------------")
                continue
            lines.append(f" --- Frame #{frame_id} ---")
            if response:
                lines.append(response)
            lines.append(" --- Bot used 0 milliseconds ---")
            lines.append("-----------------------------------------------------------------------------")
        lines.append("ERRORED!")
        if bot.error_line:
            lines.append("Response received (if any):")
            lines.append(bot.error_line)
        else:
            lines.append("No response received.")
    Path(log_name).write_text("\n".join(lines) + "\n", encoding="utf-8")
    return log_name


def remove_player_from_board(owners: list[int], strengths: list[int], player_id: int) -> None:
    for idx, owner in enumerate(owners):
        if owner == player_id:
            owners[idx] = 0
            strengths[idx] = 0


def count_alive_players(owners: list[int], actual_players: int) -> int:
    return sum(1 for player_id in range(1, actual_players + 1) if player_id in owners)


def player_has_cells(owners: list[int], player_id: int) -> bool:
    return player_id in owners


def parse_move_line(line: str, width: int, height: int, owners: list[int], player_id: int) -> list[int] | None:
    directions = [0] * (width * height)
    if line.strip() == "":
        return directions
    parts = line.split()
    if len(parts) % 3 != 0:
        return None
    try:
        values = [int(part, 10) for part in parts]
    except ValueError:
        return None
    for i in range(0, len(values), 3):
        x, y, direction = values[i], values[i + 1], values[i + 2]
        if direction < 0 or direction > 4:
            return None
        if x < 0 or x >= width or y < 0 or y >= height:
            return None
        idx = y * width + x
        if owners[idx] != player_id:
            continue
        directions[idx] = direction
    return directions


def apply_turn(
    width: int,
    height: int,
    productions: list[int],
    owners: list[int],
    strengths: list[int],
    moves_by_player: dict[int, list[int]],
) -> tuple[list[int], list[int]]:
    size = width * height
    incoming: list[dict[int, int]] = [defaultdict(int) for _ in range(size)]
    staying_owner: list[int | None] = [None] * size

    for idx in range(size):
        owner = owners[idx]
        strength = strengths[idx]
        if owner == 0:
            incoming[idx][0] += strength
            continue
        directions = moves_by_player.get(owner)
        direction = directions[idx] if directions is not None else 0
        if direction == 0:
            incoming[idx][owner] += strength
            staying_owner[idx] = owner
            continue
        dest = neighbor_index(idx, width, height, direction)
        incoming[dest][owner] += strength
        incoming[idx][owner] += 0

    post_owner = [0] * size
    post_strength = [0] * size
    for idx, bucket in enumerate(incoming):
        items = list(bucket.items())
        if not items:
            continue
        if len(items) == 1:
            owner, amount = items[0]
            post_owner[idx] = owner
            post_strength[idx] = max(0, amount)
            continue
        sums = {owner: amount for owner, amount in items}
        best_owner = 0
        best_remaining = 0
        tied = False
        total = sum(sums.values())
        for owner, amount in sums.items():
            remaining = amount - (total - amount)
            if remaining > best_remaining:
                best_owner = owner
                best_remaining = remaining
                tied = False
            elif remaining == best_remaining and remaining > 0:
                tied = True
        if best_remaining > 0 and not tied:
            post_owner[idx] = best_owner
            post_strength[idx] = best_remaining
        else:
            post_owner[idx] = 0
            post_strength[idx] = 0

    final_owner = post_owner[:]
    final_strength = post_strength[:]
    for idx in range(size):
        owner = post_owner[idx]
        if owner == 0:
            continue
        x, y = index_to_xy(idx, width)
        damage = 0
        for nx, ny in (
            ((x + 1) % width, y),
            ((x - 1) % width, y),
            (x, (y + 1) % height),
            (x, (y - 1) % height),
        ):
            nidx = ny * width + nx
            nowner = post_owner[nidx]
            nstrength = post_strength[nidx]
            if nowner != 0 and nowner != owner and nstrength > 0:
                damage += nstrength
        remaining = post_strength[idx] - damage
        if remaining < 0:
            final_owner[idx] = 0
            final_strength[idx] = 0
        else:
            final_strength[idx] = remaining

    for idx in range(size):
        owner = final_owner[idx]
        if owner == 0:
            continue
        if staying_owner[idx] == owner:
            final_strength[idx] = min(255, final_strength[idx] + productions[idx])

    return final_owner, final_strength


def build_replay(
    frames: list[list[list[int]]],
    moves: list[list[list[int]]],
    player_names: list[str],
    productions: list[int],
    width: int,
    height: int,
) -> dict[str, object]:
    return {
        "frames": frames,
        "height": height,
        "moves": moves,
        "num_frames": len(frames),
        "num_players": len(player_names),
        "player_names": player_names,
        "productions": production_matrix(productions, width, height),
        "version": 11,
        "width": width,
    }


def open_replay_path(replay_directory: str | None, run_id: int, seed: int) -> tuple[str, Path]:
    base = replay_directory if replay_directory is not None else "."
    replay_name = f"{run_id}-{seed}.hlt"
    display = f"{base}/{replay_name}" if base != "." else f"./{replay_name}"
    return display, Path(base) / replay_name


def print_quiet(
    bot_commands: list[str],
    width: int,
    height: int,
