def print_verbose_summary(
    seed: int,
    replay_display: str | None,
    ranks: dict[int, int],
    bots: list[Bot],
) -> None:
    print(f"Map seed was {seed}")
    if replay_display is not None:
        print(f"Opening a file at {replay_display}")
    for bot in bots:
        print(
            f"Player #{bot.player_id}, {bot.name}, came in rank #{ranks[bot.player_id]} "
            f"and was last alive on frame #{bot.last_alive_frame}!"
        )


def main(argv: list[str]) -> int:
    try:
        opts = parse_cli(argv)
    except ParseFailure as err:
        emit_parse_error(err)
        return 1

    if opts.help:
        sys.stdout.write(HELP_TEXT)
        return 0
    if opts.version:
        sys.stdout.write(f"\n{PROGRAM_NAME}  version: {VERSION}\n")
        return 0

    bot_commands = opts.bot_commands or []
    if not bot_commands:
        sys.stdout.write(NO_BOT_TEXT)
        return 1

    actual_players = len(bot_commands)
    map_players = actual_players
    if actual_players == 1 and opts.nplayers is not None:
        map_players = opts.nplayers
    if map_players < 1 or map_players > 6:
        for command in bot_commands:
            print(command)
        for command in bot_commands:
            print(command)
        print()
        print(INVALID_NPLAYERS_TEXT)
        return 1

    seed = choose_seed(opts.seed_raw)
    if opts.dimensions is None:
        width, height = default_dimensions(seed, map_players)
    else:
        width, height = normalize_dimensions(opts.dimensions[0], opts.dimensions[1], map_players)

    if should_segfault_dimensions(width, height, map_players):
        segfault_after_echo(bot_commands)
        return 139

    replay_display: str | None = None
    replay_path: Path | None = None
    if not opts.no_replay:
        replay_display, replay_path = open_replay_path(opts.replay_directory, now_run_id(), seed)
        assert replay_path is not None
        if replay_path.parent != Path(".") and not replay_path.parent.exists():
            sys.stderr.write(
                "terminate called after throwing an instance of 'std::runtime_error'\n"
                "  what():  Could not open file for replay\n"
            )
            os.abort()

    run_id = now_run_id()
    if replay_display is not None:
        replay_display, replay_path = open_replay_path(opts.replay_directory, run_id, seed)

    productions, owners, strengths = generate_map(seed, width, height, map_players, actual_players)

    if opts.quiet:
        for command in bot_commands:
            print(command)
        print(f"{width} {height}")
    else:
        for command in bot_commands:
            print(command)
        print(f"{width} {height}")

    bots = [Bot(player_id=i + 1, command=command) for i, command in enumerate(bot_commands)]
    for bot in bots:
        bot.launch()

    init_state_line = format_state_line(owners, strengths) + "\n"
    production_line = format_production_line(productions) + "\n"
    for bot in bots:
        if not opts.quiet:
            print(f"Init Message sent to player {bot.player_id}.")
        bot.send(f"{bot.player_id}\n")
        bot.send(f"{width} {height} \n")
        bot.send(production_line)
        bot.send(init_state_line)

    for bot in bots:
        response = bot.read_line(INIT_TIMEOUT_SECONDS, opts.ignore_timeouts)
        if response is TIMEOUT or response is None:
            bot.init_failed = True
            bot.errored = True
            bot.error_kind = "init_no_response"
            bot.error_log_name = write_error_log(bot, run_id)
            remove_player_from_board(owners, strengths, bot.player_id)
            continue
        bot.initialized = True
        bot.name = bot.command if opts.override_names else response
        bot.last_alive_frame = 0
        if not opts.quiet:
            print(f"Init Message received from player {bot.player_id}, {bot.name}.")
        bot.frame_logs.append(("init", response))

    frames = [frame_matrix(owners, strengths, width, height)]
    moves: list[list[list[int]]] = []

    if actual_players > 1 and count_alive_players(owners, actual_players) <= 1:
        pass
    else:
        max_turns = int(math.sqrt(width * height) * 10)
        for turn in range(1, max_turns + 1):
            if not opts.quiet:
                print(f"Turn {turn}")
            current_state_line = format_state_line(owners, strengths) + "\n"
            moves_by_player: dict[int, list[int]] = {}
            replay_dirs = [0] * (width * height)

            for bot in bots:
                if bot.init_failed or bot.board_removed:
                    continue
                bot.send(current_state_line)

            for bot in bots:
                if bot.init_failed or bot.board_removed:
                    continue
                response = bot.read_line(TURN_TIMEOUT_SECONDS, opts.ignore_timeouts)
                if response is TIMEOUT or response is None:
                    bot.errored = True
                    bot.error_kind = "turn_no_response"
                    bot.error_line = None
                    if not opts.quiet:
                        print(f"Bot #{bot.player_id} timeout or error (Unix) 0")
                    remove_player_from_board(owners, strengths, bot.player_id)
                    bot.board_removed = True
                    bot.error_log_name = write_error_log(bot, run_id)
                    continue
                parsed = parse_move_line(response, width, height, owners, bot.player_id)
                if parsed is None:
                    bot.errored = True
                    bot.error_kind = "invalid_move"
                    bot.error_line = response
                    if not opts.quiet:
                        print("Bot sent an invalid character - ejecting from game.")
                    remove_player_from_board(owners, strengths, bot.player_id)
                    bot.board_removed = True
                    bot.error_log_name = write_error_log(bot, run_id)
                    continue
                bot.frame_logs.append((turn, response))
                moves_by_player[bot.player_id] = parsed
                for idx, owner in enumerate(owners):
                    if owner == bot.player_id:
                        replay_dirs[idx] = parsed[idx]

            owners, strengths = apply_turn(width, height, productions, owners, strengths, moves_by_player)
            for bot in bots:
                if bot.init_failed:
                    continue
                if player_has_cells(owners, bot.player_id):
                    bot.last_alive_frame = turn

            moves.append(move_matrix(replay_dirs, width, height))
            frames.append(frame_matrix(owners, strengths, width, height))

            if actual_players > 1 and count_alive_players(owners, actual_players) <= 1:
                break

    for bot in bots:
        if bot.error_log_name is None and bot.errored:
            bot.error_log_name = write_error_log(bot, run_id)
        bot.kill()

    player_names = [bot.name for bot in bots]
    replay_data = build_replay(frames, moves, player_names, productions, width, height)
    if replay_path is not None:
        replay_path.write_text(json.dumps(replay_data, separators=(",", ":")), encoding="utf-8")

    ranking_order = sorted(
        bots,
        key=lambda bot: (bot.last_alive_frame, bot.player_id),
        reverse=True,
    )
    ranks: dict[int, int] = {}
    for rank, bot in enumerate(ranking_order, start=1):
        ranks[bot.player_id] = rank

    if opts.quiet:
        print_quiet(bot_commands, width, height, replay_display, seed, ranks, bots)
    else:
        print_verbose_summary(seed, replay_display, ranks, bots)
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

